import{_ as o,l as r,o as e,c as i,v as t,p as l,x as s,d as A,i as d,S}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SIMD 扩展：SSE / AVX / NEON","description":"","frontmatter":{"title":"SIMD 扩展：SSE / AVX / NEON","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/simd-extensions.md","filePath":"cs/simd-extensions.md","lastUpdated":1789023840000}'),E={name:"cs/simd-extensions.md"};function c(m,a,p,h,M,V){const n=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="simd-扩展-sse-avx-neon" tabindex="-1">SIMD 扩展：SSE / AVX / NEON <a class="header-anchor" href="#simd-扩展-sse-avx-neon" aria-label="Permalink to &quot;SIMD 扩展：SSE / AVX / NEON&quot;">​</a></h1><div class="epigraph"><p>定宽向量寄存器让一条指令打多个通道：x86 从 128 位 SSE 到 256/512 位 AVX，ARM 用 NEON；控制流仍付一次，数据要排齐。</p><footer>—— 据 Intel SDM；ARM ARM；Hennessy and Patterson, CA:AQA；Flynn, IEEE TC 1972 整理</footer></div><p><a href="/cs/fence-instructions">上一课</a>管标量可见性。体系结构课<a href="/cs/simd-vector">SIMD 与向量</a>已给 DLP 原则。缺口是 <strong>ISA 扩展名</strong>：SSE/AVX 与 NEON 的寄存器与打包算术，接到上一单元的 <a href="/cs/fp-mul-fma">FMA</a> 与<a href="/cs/saturating-arith">饱和</a>，而不是重写 Flynn 分类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标量 ISA 循环处理 4 个 float 要四条加。SSE：<code>xmm</code> 128 位 4×float；AVX：<code>ymm</code> 8×；AVX-512：<code>zmm</code> 与掩码。NEON：<code>v</code> 寄存器 128 位。缺口不是「什么是 SIMD」，而是这些扩展如何编码（x86 前缀/VEX/EVEX，ARM 在 A64 里）以及对齐要求（后课 alignment 会收）。</p><p>打包整数饱和乘加对应 DSP 课的端点 MUX，只是铺 \\(W\\) 路。浮点通道遵守 754，异常如何折叠到 MXCSR/FPSR 是实现细节，点名。</p><h3 id="simd-不是-gpu-simt、也不是大模型课" tabindex="-1">SIMD 不是 GPU SIMT、也不是大模型课 <a class="header-anchor" href="#simd-不是-gpu-simt、也不是大模型课" aria-label="Permalink to &quot;SIMD 不是 GPU SIMT、也不是大模型课&quot;">​</a></h3><p>SIMT 多线程束；本课是单线程向量寄存器。不把张量核、注意力算子写进 CS 栏。把 AVX 当「训练加速器产品」，对照课失焦。</p><p><span class="marginnote">Intel SDM 卷 1/2 SIMD 章；ARM NEON。CA:AQA 数据级并行。Flynn 1972 分类名。RVV 下一课才是可变 VL。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器自动向量化或内建函数。调用约定：SysV/AAPCS 如何传向量寄存器——ABI 课。上下文切换要保存宽寄存器，<a href="/cs/fpu-lazy">FPU lazy</a> 同类问题放大。内存：连续 load 最快；gather 是 AVX2/AVX-512/SVE 后加，回到不规则。</p>',11)),(e(),l(S,null,{default:s(()=>[d(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SC%5B%22%E6%A0%87%E9%87%8F%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20PACK%5B%22%E6%89%93%E5%8C%85%E5%88%B0%20xmm%2Fymm%2Fv%22%5D%0A%20%20PACK%20--%3E%20ALU%5B%22%E9%80%9A%E9%81%93%E5%B9%B6%E8%A1%8C%20ALU%2FFMA%22%5D%0A%20%20ALU%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ARVV%20%E6%8A%8A%E5%AE%BD%E5%BA%A6%E6%94%B9%E6%88%90%20VL%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 x86 微码：宽指令可能多 μop 或走专用端口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课 RVV 用 <code>vl</code> 动态长度，避免 AVX 的 128/256/512 分代。压缩指令课与 SIMD 正交。本课把工业定宽 SIMD 钉在 ISA 对照轴上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部助记符，不写 AVX-512 许可证政治。不把图像卷积当作业。不进入量化金融向量定价。</p><p>后课默认：SSE/AVX/NEON 是定宽打包 SIMD；FMA 与饱和在通道上重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>定宽寄存器打包多元素；编码因 x86/ARM 而异。</li><li>接 FMA 与饱和 ALU，不接 SIMT。</li><li>下一课 RISC-V 向量改可变 VL。</li><li>出处：Intel SDM；ARM ARM；Hennessy and Patterson, CA:AQA；Flynn 1972。</li></ul>',8))])}const u=o(E,[["render",c]]);export{f as __pageData,u as default};
